-- Open courseware entries researched 2026-11-27 (Michelle Rogers Executive Agent).
-- 29 free college/university courses across 8 subject areas; every URL was
-- confirmed against a live page during research. Idempotent: rows whose
-- source_url (research) or title (knowledge) already exist are skipped.
-- Schema notes (live-verified 2026-11-28): executive_research.kind is
-- constrained to source/analysis/document/curriculum/reference -> 'curriculum';
-- executive.knowledge.summary is NOT NULL -> supplied from the research notes;
-- knowledge.verification vocabulary is verified/reported/projected/planned ->
-- 'verified' (each source page was opened and checked during research).

-- 1) Research table (console Research tab reads public.executive_research)
insert into public.executive_research (title, kind, source_url, summary, verified, retrieved_at, provenance)
select v.title, 'curriculum', v.url, v.summary, true, now(),
  jsonb_build_object('catalogue','open-courseware','subject',v.subject,'provider',v.provider,'free_terms',v.free_terms)
from (values
('CS50x: Introduction to Computer Science — Harvard University','https://cs50.harvard.edu/x/2019/','Harvard''s flagship introduction to computer science and programming (C, Python, SQL, web basics), published as CS50''s own free OpenCourseWare with lectures, notes, slides, source code, and problem sets that can be submitted for automated feedback.','Computer Science & Programming Fundamentals','Harvard University','Fully free via CS50 OpenCourseWare; free CS50 certificate at 70% or higher; optional paid edX verified certificate'),
('6.0001 Introduction to Computer Science and Programming in Python — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/6-0001-introduction-to-computer-science-and-programming-in-python-fall-2016/resources/lecture-notes/','MIT''s introductory programming course in Python covering computation, branching, iteration, functions, data structures, and debugging; the OCW site includes lecture notes and videos, problem sets, and programming assignments.','Computer Science & Programming Fundamentals','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, Creative Commons BY-NC-SA); no certificate or credit'),
('CS61A: The Structure and Interpretation of Computer Programs — University of California, Berkeley','https://cs61a.org/fa26/syllabus/','Berkeley''s introductory CS course on abstraction, recursion, interpreters, and data structures in Python and Scheme, with a fully public course site: lectures, labs, homeworks, projects, and the free online textbook Composing Programs.','Computer Science & Programming Fundamentals','University of California, Berkeley','Free public course site and free online textbook; note that some lecture recordings may require a Berkeley login'),
('CS106A: Programming Methodology — Stanford University','https://see.stanford.edu/Course/CS106A/191','Stanford Engineering Everywhere''s complete version of the classic introductory programming course (Java/Karel, taught by Mehran Sahami): all 28 lecture videos with transcripts, plus every handout, assignment, and starter code file.','Computer Science & Programming Fundamentals','Stanford University','Fully free, no registration (Stanford Engineering Everywhere, CC BY-NC-SA 4.0); no credit or certificate'),
('Full Stack Open — University of Helsinki','https://fullstackopen.com/en/part0/general_info/','A 14-part deep dive into modern JavaScript web development — React, Node/Express, GraphQL, TypeScript, React Native, CI/CD, containers, and relational databases — with extensive hands-on exercises throughout.','Software Engineering & Full-Stack Web Development','University of Helsinki','Totally free, including a free certificate; optional free ECTS credits via University of Helsinki Open University enrollment (material CC BY-NC-SA)'),
('CS50''s Web Programming with Python and JavaScript — Harvard University','https://harvardonline.harvard.edu/course/cs50s-web-programming-python-javascript','Harvard''s 12-week follow-up to CS50 covering HTML/CSS, Git, Python and Django, SQL and data models, JavaScript, user interfaces, testing, and CI/CD, with lectures and projects.','Software Engineering & Full-Stack Web Development','Harvard University','Free to audit on edX; paid verified certificate optional (listings vary, $199-$299); free CS50 certificate also available'),
('6.005 Elements of Software Construction — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/6-005-elements-of-software-construction-fall-2008/','MIT''s software engineering course on writing code that is safe from bugs, easy to understand, and ready for change: specifications, testing, state machines, abstract data types, design patterns, and concurrency, with lecture notes, problem sets, programming assignments, and projects.','Software Engineering & Full-Stack Web Development','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, Creative Commons); no certificate or credit'),
('CS229: Machine Learning — Stanford University','https://cs229.stanford.edu/index.html-backup-fall21','Stanford''s graduate machine learning course (supervised and unsupervised learning, learning theory, reinforcement learning) with public lecture notes and problem sets from the course site.','Artificial Intelligence & Machine Learning','Stanford University','Free public course materials (notes and problem sets); note a separate paid Stanford Online enrollment version of CS229 also exists'),
('6.036 Introduction to Machine Learning — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/6-036-introduction-to-machine-learning-fall-2020/','MIT''s undergraduate machine learning course covering classification, regression, neural networks, and reinforcement learning, with lectures, notes, exercises, labs, and homework on OCW (also mirrored in MIT''s Open Learning Library).','Artificial Intelligence & Machine Learning','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, Creative Commons); no certificate or credit'),
('CS50''s Introduction to Artificial Intelligence with Python — Harvard University','https://cs50.harvard.edu/ai/','Harvard''s 7-week AI course covering search, knowledge representation, uncertainty, optimization, machine learning, and neural networks, taught through lectures and hands-on Python projects, published free on CS50''s OpenCourseWare site.','Artificial Intelligence & Machine Learning','Harvard University','Fully free via CS50 OpenCourseWare; free CS50 certificate at 70% or higher; optional paid edX verified certificate'),
('CS224N: Natural Language Processing with Deep Learning — Stanford University','https://web.stanford.edu/class/cs224n/','Stanford''s NLP course on word vectors, recurrent and transformer models, and large language models, with public lecture slides, course notes, and programming assignments on the class website.','Artificial Intelligence & Machine Learning','Stanford University','Free public slides, notes, and assignments; current-term lecture videos are for enrolled students only (earlier lectures are free on YouTube)'),
('CS294/194-196: Large Language Model Agents (MOOC) — University of California, Berkeley','https://rdi.berkeley.edu/llm-agents/f24','Berkeley RDI''s free MOOC on LLM agents (Dawn Song and guest lecturers): reasoning, planning, tool use, agent frameworks such as AutoGen and DSPy, evaluation, and agent safety, with public lecture videos, quizzes, and labs.','Artificial Intelligence & Machine Learning','University of California, Berkeley','Free MOOC — lecture videos and materials remain publicly available; the certificate coursework window has closed'),
('Data 8: The Foundations of Data Science — University of California, Berkeley','https://data8.org/','Berkeley''s flagship introductory data science course combining inferential thinking, computational thinking, and real-world data analysis in Python/Jupyter; all materials — the interactive textbook Computational and Inferential Thinking, lectures, labs, homeworks, and projects — are published as open educational resources.','Data Science & Statistics','University of California, Berkeley','Free course materials and interactive textbook (textbook CC BY-NC-ND 4.0; most other materials under MIT, BSD, or CC licenses)'),
('Statistical Reasoning (Open & Free) — Carnegie Mellon University','https://oli.cmu.edu/courses/statistical-reasoning-copy/','Carnegie Mellon Open Learning Initiative''s self-paced introductory statistics course covering data production, displays, correlation, probability, sampling distributions, and inference, with interactive exercises and immediate feedback.','Data Science & Statistics','Carnegie Mellon University','Free for independent learners (Open & Free version: course materials only — no instructor, tests, credit, or certificate)'),
('Probability & Statistics (Open & Free) — Carnegie Mellon University','https://oli.cmu.edu/courses/probability-statistics-open-free/','CMU OLI''s combined probability and statistics course with all expository text, simulations, and StatTutor labs, covering exploratory analysis, probability, distributions, and statistical inference.','Data Science & Statistics','Carnegie Mellon University','Free for independent learners (Open & Free version: full learning materials; scored tests omitted; no instructor, credit, or certificate)'),
('Introductory Statistics 2e (textbook) — Rice University (OpenStax)','https://openstax.org/details/books/introductory-statistics-2e','OpenStax''s peer-reviewed one-semester introductory statistics textbook (sampling, descriptive statistics, probability, random variables, hypothesis testing, regression), readable free online or as a PDF download.','Data Science & Statistics','Rice University (OpenStax)','Fully free textbook (web view and PDF) under a Creative Commons license; low-cost print optional'),
('DevOps with Docker — University of Helsinki','https://github.com/mamelukki/docker-hy.github.io','The University of Helsinki''s open course material repository for its Docker course: containers and images, Docker Compose, networking and volumes, deployment pipelines, and container security and optimization, in three parts with exercises.','Cloud Computing & DevOps','University of Helsinki','Fully free course material (CC BY-NC-SA 4.0); optional university credits (1-3) via enrollment'),
('DevOps with Kubernetes — University of Helsinki','https://courses.mooc.fi/org/uh-cs/courses/devops-with-kubernetes-2026','Helsinki''s follow-on DevOps course on MOOC.fi covering Kubernetes basics, networking and storage, organizing clusters, monitoring, deploying to Google Kubernetes Engine, deployment pipelines, and GitOps, chapter by chapter with exercises and a course project.','Cloud Computing & DevOps','University of Helsinki','Fully free course material (CC BY-NC-SA) via MOOC.fi'),
('6.824 Distributed Computer Systems Engineering — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/6-824-distributed-computer-systems-engineering-spring-2006/pages/syllabus/','MIT''s graduate distributed systems course — the foundation of cloud infrastructure — covering RPC, crash recovery, cache consistency, two-phase commit, and Paxos through research papers, with lecture notes, programming labs (building a cluster file system), exams, and a final project.','Cloud Computing & DevOps','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, Creative Commons); no certificate or credit'),
('CS50''s Introduction to Cybersecurity — Harvard University','https://harvardonline.harvard.edu/course/cs50s-introduction-cybersecurity','Harvard''s introduction to cybersecurity for technical and non-technical audiences: securing accounts, data, systems, and software, covering passwords and SSO, brute-force and phishing/social-engineering attacks, and cryptography basics.','Cybersecurity Fundamentals','Harvard University','Free audit learning on edX (select materials); HarvardX verified certificate $449; a free CS50 certificate is also available'),
('6.858 Computer Systems Security — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/6-858-computer-systems-security-fall-2014/','MIT''s graduate course on designing and implementing secure computer systems: threat models, buffer overflows, privilege separation, capabilities, sandboxing, web and network security, and authentication, with lecture videos and notes, six hands-on labs, exams with solutions, and a final project.','Cybersecurity Fundamentals','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, Creative Commons); no certificate or credit'),
('CS155: Computer and Network Security — Stanford University','https://cs155.stanford.edu/syllabus.html','Stanford''s course on principles of building secure systems: control-hijacking attacks and defenses, OS security, isolation and sandboxing, web security model and attacks, and cryptography, with public lecture slides, readings, sample exams, and project descriptions.','Cybersecurity Fundamentals','Stanford University','Free public syllabus, lecture slides, and readings; lecture recordings require a Stanford Canvas login'),
('15.390 New Enterprises — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/15-390-new-enterprises-spring-2013/','MIT Sloan''s flagship entrepreneurship course (the class behind the Disciplined Entrepreneurship framework): identifying and quantifying market opportunities, building a business plan section by section, investor strategy and pitch, and financing — with lecture notes, tutorial videos, and assignments.','Entrepreneurship, Business & Fundraising','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, Creative Commons); no certificate or credit'),
('ECON 252: Financial Markets — Yale University','https://online.yale.edu/courses/financial-markets','Robert Shiller''s Yale course on how financial institutions manage risk and foster enterprise: securities, insurance, banking, behavioral finance, and financial crises, delivered via Open Yale Courses, Coursera, and YouTube with full lectures, transcripts, syllabus, readings, and exams.','Entrepreneurship, Business & Fundraising','Yale University','Fully free via Open Yale Courses (no registration, credit, or certificate); also free on Coursera with an optional paid certificate (about $49, variable pricing)'),
('Entrepreneurship (textbook) — Rice University (OpenStax)','https://openstax.org/details/books/entrepreneurship','OpenStax''s peer-reviewed introductory entrepreneurship textbook (15 chapters): the entrepreneurial mindset, opportunity recognition, business models, financing, marketing, and innovation, with review and case questions throughout.','Entrepreneurship, Business & Fundraising','Rice University (OpenStax)','Fully free textbook (web view and PDF) under Creative Commons; low-cost print optional'),
('Entrepreneurship Specialization (Wharton) — University of Pennsylvania','https://www.classcentral.com/course/wharton-entrepreneurship-18932','Wharton School''s Coursera specialization on the conception, design, organization, and management of new enterprises: developing the opportunity, launching, growth strategies, financing and profitability, plus a capstone project.','Entrepreneurship, Business & Fundraising','University of Pennsylvania','Free to audit on Coursera; certificate/specialization paid (financial aid available)'),
('6.042J Mathematics for Computer Science — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/','MIT''s discrete mathematics course for computer scientists (Leighton and van Dijk): proofs, logic, induction, graph theory, number theory, and probability, with lecture videos, problem sets, and exams with solutions.','Mathematics for Computer Science','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, CC BY-NC-SA); no certificate or credit'),
('18.06 Linear Algebra — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/18-06-linear-algebra-spring-2010/','Gilbert Strang''s celebrated linear algebra course — matrices, vector spaces, eigenvalues, and least squares, the mathematical backbone of machine learning — with full lecture videos, problem sets with solutions, and exams with solutions.','Mathematics for Computer Science','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, Creative Commons); no certificate or credit'),
('18.01 Single Variable Calculus — Massachusetts Institute of Technology','https://ocw.mit.edu/courses/18-01-single-variable-calculus-fall-2006/pages/syllabus/','MIT''s first-semester calculus course: differentiation and integration of functions of one variable, the Fundamental Theorem of Calculus, and applications, with lecture notes, problem sets with solutions, and exams with solutions (an OCW Scholar version adds segmented lecture videos for independent study).','Mathematics for Computer Science','Massachusetts Institute of Technology','Fully free materials (MIT OpenCourseWare, Creative Commons); no certificate or credit')
) as v(title, url, summary, subject, provider, free_terms)
where not exists (select 1 from public.executive_research r where r.source_url = v.url);

